import fs from 'node:fs';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';import {buildConservationUnitLookup} from '/home/vantt/projects/forgentX-phase00-documentation-authority-unification/scripts/check-doc-inventory-gates.mjs';
const root=process.cwd(),r='plans/260925-documentation-authority-unification/reports/phase-06/',index=JSON.parse(fs.readFileSync(r+'bounded-review-set-resume.json')),sha=s=>crypto.createHash('sha256').update(s).digest('hex'),lookups=new Map(),shards=new Map(),all=[];
function lookup(pin){if(!lookups.has(pin))lookups.set(pin,buildConservationUnitLookup(root,pin));return lookups.get(pin);}
function checkUnit(u,d,pin,kind){if(!u)return;const text=execFileSync('git',['show',(u.contentCommit||pin)+':'+u.path],{encoding:'utf8',maxBuffer:100e6});if(!u.nativeDigest){assert.equal(u.text,text);assert.equal(d,sha(text));return;}const units=lookup(u.contentCommit||pin)(u.path);if(u.path.endsWith('.md')){const unit=units.find(v=>v.anchor===u.anchor&&v.textDigest===u.nativeDigest);assert(unit,'native unit '+u.path+'#'+u.anchor);assert.equal(u.text,unit.sectionText||unit.text);assert.equal(u.nativeDigest,unit.textDigest);assert.equal(d,kind==='alias-accounting'?sha(u.text):unit.textDigest);}else{assert.equal(u.text,text);assert.equal(d,sha(text));}}
for(const req of index.requests){const md=fs.readFileSync(req.pack,'utf8'),side=JSON.parse(fs.readFileSync(req.pack+'.json')),request=fs.readFileSync(req.request,'utf8');assert(side.rows.length<=80);assert.equal(side.rows.length,req.entries);assert.equal(sha(md),req.packSHA256);assert.equal(sha(md),side.packSHA256);assert(request.includes(req.packSHA256));assert.deepEqual(side.differingDigestRows,side.rows.filter(e=>e.sourceDigest!==e.targetDigest).map(e=>e.id));assert.deepEqual(side.absentTargetRows,side.rows.filter(e=>e.targetDigest==='none').map(e=>e.id));assert.equal(new Set(side.rows.map(e=>e.id)).size,side.rows.length);
 for(const e of side.rows){for(const d of [e.sourceDigest,e.targetDigest])assert(d==='none'||/^[0-9a-f]{64}$/.test(d),e.id);for(const u of [e.source,e.target])if(u){assert(md.includes(u.text),'full displayed '+e.id);assert(md.includes(sha(u.text)),'shown digest '+e.id);}try{checkUnit(e.source,e.sourceDigest,side.contentCommit,e.kind);checkUnit(e.target,e.targetDigest,side.contentCommit,e.kind);}catch(err){console.error(e.id);throw err;}
 if(e.kind.startsWith('ordinary-')){if(!shards.has(e.shard))shards.set(e.shard,JSON.parse(fs.readFileSync(e.shard)));const shard=shards.get(e.shard),decision=[...(shard.claims||[]),...(shard.registryGaps||[])].find(x=>x.claimId===e.id);assert.deepEqual(e.decision,decision);assert.equal(e.claimId,e.id);assert(decision.reviewStatus!=='reviewed');if(decision.sourceUnitDigest)assert(e.sourceDigest.startsWith(decision.sourceUnitDigest),e.id+' source mismatch '+e.sourceDigest+' '+decision.sourceUnitDigest);if(decision.targetOwner){assert.equal(e.target.path,decision.targetOwner);assert.equal(e.target.anchor,decision.targetAnchor);assert(e.targetDigest.startsWith(decision.targetUnitDigest));}}
 all.push(e);
 }
}
const data=JSON.parse(fs.readFileSync('/tmp/fgos-work/resume-truth/pack-entries.json')),a=JSON.parse(fs.readFileSync(r+'root-boundary-sync-accounting.json'));
assert.equal(all.length,303);assert.equal(new Set(all.map(e=>e.id)).size,303);assert.equal(data.truth.length,35);assert.equal(data.pending.length,18);assert.equal(data.merge.length,250);assert.equal(data.pending.filter(e=>e.kind==='alias-accounting').length,4);assert.equal(data.pending.filter(e=>e.kind==='retained-path-accounting').length,5);assert.equal(data.pending.filter(e=>e.kind.startsWith('ordinary-')).length,9);
for(const b of [...a.bindings.rows.map(x=>x.after),...a.bindings.newCurrentRows,...a.bindings.newGapRows,...a.bindings.existingGapRebindings.map(x=>x.after)])assert(data.merge.some(e=>e.id===b.claimId),'missing merge '+b.claimId);
for(const b of a.retiredNativeFullDigestRepair){assert(b.afterDigest.startsWith(b.beforeDigest));const entries=data.merge.filter(e=>e.id===b.claimId);assert.equal(entries.length,1);assert.equal(entries[0].sourceDigest,b.afterDigest);}
const proof={contentCommit:index.contentCommit,requests:index.requests.map(q=>({request:q.request,pack:q.pack,entries:q.entries,packSHA256:q.packSHA256})),totalEntries:all.length,fullNativeShownTextAndDigests:true,exactPendingDecisionEquality:true,allOrdinaryRowsPending:true,completeScopeEquality:true,uniqueIDs:true,differingAndAbsentListsEqual:true,retiredFullDigestExpansions:a.retiredNativeFullDigestRepair,helperSource:fs.readFileSync(import.meta.filename,'utf8')};fs.writeFileSync(r+'bounded-review-validation-resume.json',JSON.stringify(proof,null,2)+'\n');console.log('Validated',all.length,'entries',index.requests.map(q=>q.entries));
